            ('O-5b:10', '10 nearest to Reykjavik: geography <-> set = haversine oracle set', (SELECT md5(string_agg(log_id::text, ',' ORDER BY log_id)) FROM (SELECT f.log_id FROM log_regex_gis.flat_numeric f WHERE f.latitude_degrees IS NOT NULL AND f.longitude_degrees IS NOT NULL ORDER BY (2 * 6371008.7714 * asin(least(1, sqrt(power(sin((radians(f.latitude_degrees::float8) - radians(64.1466)) / 2), 2) + cos(radians(f.latitude_degrees::float8)) * cos(radians(64.1466)) * power(sin((radians(f.longitude_degrees::float8) - radians(-21.9426)) / 2), 2))))), f.log_id LIMIT 10) s), (SELECT md5(string_agg(log_id::text, ',' ORDER BY log_id)) FROM (SELECT t.log_id FROM log_regex_gis.flat_geog t WHERE t.geog IS NOT NULL ORDER BY t.geog OPERATOR(postgis.<->) postgis.geography(postgis.ST_SetSRID(postgis.ST_MakePoint(-21.9426, 64.1466), 4326)), t.log_id LIMIT 10) s)),
            ('O-5b:100', '100 nearest to Reykjavik: geography <-> set = haversine oracle set', (SELECT md5(string_agg(log_id::text, ',' ORDER BY log_id)) FROM (SELECT f.log_id FROM log_regex_gis.flat_numeric f WHERE f.latitude_degrees IS NOT NULL AND f.longitude_degrees IS NOT NULL ORDER BY (2 * 6371008.7714 * asin(least(1, sqrt(power(sin((radians(f.latitude_degrees::float8) - radians(64.1466)) / 2), 2) + cos(radians(f.latitude_degrees::float8)) * cos(radians(64.1466)) * power(sin((radians(f.longitude_degrees::float8) - radians(-21.9426)) / 2), 2))))), f.log_id LIMIT 100) s), (SELECT md5(string_agg(log_id::text, ',' ORDER BY log_id)) FROM (SELECT t.log_id FROM log_regex_gis.flat_geog t WHERE t.geog IS NOT NULL ORDER BY t.geog OPERATOR(postgis.<->) postgis.geography(postgis.ST_SetSRID(postgis.ST_MakePoint(-21.9426, 64.1466), 4326)), t.log_id LIMIT 100) s)),
            ('E1', 'distance (0,180)-(0,-180): geography metres (3 dp) / geometry degrees', '0.000/360', (SELECT round(postgis.ST_Distance(postgis.geography(postgis.ST_SetSRID(postgis.ST_MakePoint(180, 0), 4326)), postgis.geography(postgis.ST_SetSRID(postgis.ST_MakePoint(-180, 0), 4326)))::numeric, 3) || '/' || postgis.ST_Distance(postgis.ST_SetSRID(postgis.ST_MakePoint(180, 0), 4326), postgis.ST_SetSRID(postgis.ST_MakePoint(-180, 0), 4326)))),
            ('E2', 'distance between pole points (90,180) and (90,0), geography metres (3 dp)', '0.000', (SELECT round(postgis.ST_Distance(postgis.geography(postgis.ST_SetSRID(postgis.ST_MakePoint(180, 90), 4326)), postgis.geography(postgis.ST_SetSRID(postgis.ST_MakePoint(0, 90), 4326)))::numeric, 3)::text)),
            ('E3', 'B6 edge point log_id 2272 (90,180): ST_Within / ST_Intersects with envelope (-180 80, 180 90)', 'false/true', (SELECT postgis.ST_Within(geom, postgis.ST_MakeEnvelope(-180, 80, 180, 90, 4326))::text || '/' || postgis.ST_Intersects(geom, postgis.ST_MakeEnvelope(-180, 80, 180, 90, 4326))::text FROM log_regex_gis.flat_geom WHERE log_id = 2272))
        ) AS c (id, name, expected, actual)
    LOOP
        IF chk.expected IS NOT DISTINCT FROM chk.actual THEN
            RAISE NOTICE '% PASS  %: %', chk.id, chk.name, chk.actual;
        ELSE
            v_failed := v_failed + 1;
            RAISE WARNING '% FAIL  %: expected %, actual %', chk.id, chk.name, chk.expected, chk.actual;
        END IF;
    END LOOP;
    PERFORM set_config('step7b.verify47', v_failed::text, false);
END
$verify$;
DO $info$
DECLARE
    r record;
BEGIN
    FOR r IN SELECT i.label, i.value FROM (VALUES
            ('INFO postgis_full_version', (SELECT postgis.postgis_full_version())),
            ('INFO O-3a max |sphere - haversine| metres', (SELECT max(abs(postgis.ST_Distance(g.geog, postgis.geography(postgis.ST_SetSRID(postgis.ST_MakePoint(c.lon, c.lat), 4326)), false) - (2 * 6371008.7714 * asin(least(1, sqrt(power(sin((radians(f.latitude_degrees::float8) - radians(c.lat)) / 2), 2) + cos(radians(f.latitude_degrees::float8)) * cos(radians(c.lat)) * power(sin((radians(f.longitude_degrees::float8) - radians(c.lon)) / 2), 2)))))))::text FROM log_regex_gis.flat_geog g JOIN log_regex_gis.flat_numeric f ON f.log_id = g.log_id CROSS JOIN (VALUES (40.7128::float8, -74.0060::float8), (19.0760::float8, 72.8777::float8), (64.1466::float8, -21.9426::float8), (51.5074::float8, -0.1278::float8), (0.0::float8, 180.0::float8), (90.0::float8, 0.0::float8)) AS c (lat, lon) WHERE g.geog IS NOT NULL)),
            ('INFO O-4a max relative |spheroid - sphere| / sphere', (SELECT max(abs(x.sph - x.sphere) / x.sphere)::text FROM (SELECT postgis.ST_Distance(g.geog, postgis.geography(postgis.ST_SetSRID(postgis.ST_MakePoint(c.lon, c.lat), 4326)), true) AS sph, postgis.ST_Distance(g.geog, postgis.geography(postgis.ST_SetSRID(postgis.ST_MakePoint(c.lon, c.lat), 4326)), false) AS sphere FROM log_regex_gis.flat_geog g CROSS JOIN (VALUES (40.7128::float8, -74.0060::float8), (19.0760::float8, 72.8777::float8), (64.1466::float8, -21.9426::float8), (51.5074::float8, -0.1278::float8), (0.0::float8, 180.0::float8), (90.0::float8, 0.0::float8)) AS c (lat, lon) WHERE g.geog IS NOT NULL) x WHERE x.sphere > 0)),
            ('INFO O-5 geography <-> semantics (100 nearest to Reykjavik): max |<-> - sphere| / max |<-> - spheroid| metres', (SELECT max(abs(x.op - x.sphere)) || ' / ' || max(abs(x.op - x.spheroid)) FROM (SELECT t.geog OPERATOR(postgis.<->) postgis.geography(postgis.ST_SetSRID(postgis.ST_MakePoint(-21.9426, 64.1466), 4326)) AS op, postgis.ST_Distance(t.geog, postgis.geography(postgis.ST_SetSRID(postgis.ST_MakePoint(-21.9426, 64.1466), 4326)), false) AS sphere, postgis.ST_Distance(t.geog, postgis.geography(postgis.ST_SetSRID(postgis.ST_MakePoint(-21.9426, 64.1466), 4326)), true) AS spheroid FROM log_regex_gis.flat_geog t WHERE t.geog IS NOT NULL ORDER BY t.geog OPERATOR(postgis.<->) postgis.geography(postgis.ST_SetSRID(postgis.ST_MakePoint(-21.9426, 64.1466), 4326)) LIMIT 100) x))
        ) AS i (label, value)
    LOOP
        RAISE NOTICE '%: %', r.label, r.value;
    END LOOP;
END
$info$;
DO $verdict$
BEGIN
    IF current_setting('step7b.verify47')::integer > 0 THEN
        RAISE EXCEPTION 'sql/47 PostGIS setup verification FAILED: % of 155 checks', current_setting('step7b.verify47') USING ERRCODE = 'LR021';
    END IF;
    RAISE NOTICE 'sql/47 PostGIS setup verification PASSED: all 155 checks';
END
$verdict$;

DO $e4$
DECLARE
    v_state text;
BEGIN
    BEGIN
        PERFORM postgis.ST_Intersects(postgis.ST_SetSRID(postgis.ST_MakePoint(0, 0), 4326), postgis.ST_SetSRID(postgis.ST_MakePoint(0, 0), 3857));
        v_state := 'no error';
    EXCEPTION WHEN OTHERS THEN
        v_state := 'error ' || SQLSTATE || ': ' || SQLERRM;
    END;
    IF v_state NOT LIKE 'error%' THEN
        RAISE EXCEPTION 'E4 FAIL  mixing SRID 4326 and 3857 did not raise an error' USING ERRCODE = 'LR021';
    END IF;
    RAISE NOTICE 'E4 PASS  mixing SRID 4326 and 3857 raises an error: %', v_state;
END
$e4$;
DO $harness$ BEGIN RAISE NOTICE 'Step 7B harness PASSED: sql/45 gate, sql/46 gate, sql/47 verification and E4 inside one transaction'; END $harness$;
ROLLBACK;
